    [/^(.+) · (未过门槛 · 诊断首选|通过门槛 · 候选首选) (.+)$/, (_, status, type, trip) => `${status} · ${type.startsWith("未") ? "Below threshold · Top diagnostic" : "Passed threshold · Top candidate"} ${trip}`],
    [/^(.+) · 无已评分候选$/, "$1 · No scored candidate"],
    [/^独立 canonical s 轴 · (.+) · ([\d,.]+) 个片段$/, "Independent canonical s axis · $1 · $2 segments"],
    [/^(.+) 方向 (.+) 全天时间距离图$/, "$1 direction · $2 full-day time–distance diagram"],
    [/^(.+)，打开逐趟检查$/, "$1; open trip-by-trip review"],
    [/^列表显示前 200 \/ ([\d,.]+) 条；完整差异见下方可追溯 JSON。$/, "Showing the first 200 / $1 rows; complete differences are in the traceable JSON below."],
    [/^(.+) 是固定单日原始证据截面。日期边缘截断不是 trip 起点或终点；缺失跨日上下文不能被自动补全。$/, "$1 is a fixed single-day source-evidence slice. Day-edge truncation is not a trip start or end; missing cross-day context cannot be automatically reconstructed."],
    [/^当前子片段 (.+)；实际双源覆盖 (.+)。/, "Current subsegment $1; observed two-source coverage $2. "],
    [/^候选边界 (.+)；成员原始覆盖 (.+)；首次确定方向 (.+)，未知方向累计 (.+) 秒。/, "Candidate boundaries $1; original member coverage $2; first definite direction $3; total unknown-direction duration $4 seconds. "],
    [/^当前实际成员覆盖 (.+)；持久化候选区间 (.+)（外缘可能只是日期截断，不能当作实际 trip 始终点）。/, "Observed member coverage $1; persisted candidate interval $2 (outer edges may be day truncation, not actual trip endpoints). "],
    [/^所选参考轴：有效 AVL 投影 ([\d,.]+) 点，OFF_REFERENCE ([\d,.]+) 点仅作诊断；APC 站点歧义 ([\d,.]+) 个位置候选不当成唯一 s 支持。有效 coverage、NO_EVIDENCE 窗口与阈值详见下方原始证据；缺证据不自动说明未运行。$/, "Selected reference: $1 valid AVL projections; $2 OFF_REFERENCE points are diagnostic only. $3 ambiguous APC stop-position candidates are not treated as unique s support. See source evidence below for coverage, NO_EVIDENCE windows and thresholds; missing evidence does not imply no service."],
    [/^从已产生整趟评分、但未通过门槛的候选中按原评分由低到高展示，排除上方已展示的候选。总计 (.+) 个未过门槛，(.+) 个已在最终列表保留；此处展示 (\d+) 个。仅检索到但没有有效评分的 NO_EVIDENCE 项不补分数。(诊断曲线默认关闭，可勾选对比。|当前无最终候选，默认叠加诊断曲线；这不代表接受匹配。)$/, (_, total, shown, count, end) => `Candidates with whole-trip scores that failed a threshold are shown from lowest to highest original score, excluding those already displayed above. ${total} failed; ${shown} are retained in the final list; ${count} are shown here. Retrieved NO_EVIDENCE items without valid scores are not assigned fabricated scores. ${end.startsWith("诊断") ? "Diagnostic curves are off by default; select them to compare." : "No final candidates are available, so diagnostic curves are overlaid by default; this does not mean the match is accepted."}`],
    [/^(.+) · Route 29 · (.+) · ([\d,.]+) 辆车 \/ ([\d,.]+) 个片段 · ([\d,.]+) 个展示通过门槛候选 \/ ([\d,.]+) 个展示未过门槛候选 \/ ([\d,.]+) 个无已评分候选。总览不受左侧单车筛选限制。$/, (_, day, mode, vehicles, segments, accepted, fallback, missing) => `${day} · Route 29 · ${window.TidesI18n.translate(mode)} · ${vehicles} vehicles / ${segments} segments · ${accepted} show a threshold-passing candidate / ${fallback} show a below-threshold candidate / ${missing} have no scored candidate. The overview is not limited by the left-side vehicle filter.`],
    [/^本车日选入 ([\d,.]+) 条来源记录，排除其它线路 ([\d,.]+) 条（包含 929，不与 29 合并）。当前候选成员 ([\d,.]+) AVL \/ ([\d,.]+) APC；加载上下文单独保留。父实验全线路的 APC 保留与 AVL 去重审计仍在旧版本，本页不能声称展示全部线路 APC。$/, "This vehicle day includes $1 source records and excludes $2 other-route records (including 929, which is not merged with 29). Current candidate members: $3 AVL / $4 APC; loaded context is retained separately. The parent experiment's all-route APC retention and AVL deduplication audit remains in the earlier version; this page does not display APC for all routes."],
    [/^当前候选含 ([\d,.]+) 条 AVL \/ ([\d,.]+) 条 APC；上下文不是成员，跨候选记录不能重复计数。原 CSV、被过滤记录与副本追溯仍保留。$/, "The current candidate contains $1 AVL / $2 APC records. Context is not membership; records shared across candidates must not be double-counted. Original CSVs, filtered records and duplicate lineage are retained."],
    [/^候选 AVL 成员 ([\d,.]+) · 已加载有效 GPS ([\d,.]+)（可含上下文）$/, "Candidate AVL members $1 · Loaded valid GPS $2 (may include context)"],
    [/^当天 AVL (去重保留|来源) ([\d,.]+) 行 · 不代表匹配$/, (_, type, n) => `Daily AVL ${type === "来源" ? "source" : "retained deduplicated"} rows ${n} · Does not imply a match`],
    [/^片段成员 ([\d,.]+) 行 · 窗口含上下文$/, "Segment members: $1 rows · Window includes context"],
    [/^(.+) · 方向冲突窗口 ([\d,.]+) · (.+)$/, (_, prefix, n, id) => `${window.TidesI18n.translate(prefix)} · Direction-conflict windows ${n} · ${id}`],
    [/^方向冲突窗口 ([\d,.]+) · (.+)$/, (_, n, rest) => `Direction-conflict windows ${n} · ${window.TidesI18n.translate(rest)}`],
    [/^(.+) · (线路|源线路) (.+)$/, (_, prefix, sourceLabel, routes) => `${prefix} · Source routes ${routes}`],
    [/^(.+) · ([\d,.]+) (AVL 来源行|成员 GPS|同窗 GPS) · ([\d,.]+) APC$/, (_, prefix, count, label, apc) => `${prefix} · ${count} ${{"AVL 来源行":"AVL source rows","成员 GPS":"member GPS","同窗 GPS":"same-window GPS"}[label]} · ${apc} APC`],
    [/^([\d,.]+) (AVL 来源行|成员 GPS|同窗 GPS) · ([\d,.]+) APC$/, (_, count, label, apc) => `${count} ${{"AVL 来源行":"AVL source rows","成员 GPS":"member GPS","同窗 GPS":"same-window GPS"}[label]} · ${apc} APC`],
    [/^(.+) · 同车全日$/, "$1 · Full vehicle day"],
    [/^(上|下)一个(车辆日对象|浏览对象|行程|方向候选审查对象|方向候选)(.*)$/, (_, dir, type, rest) => `${dir === "上" ? "Previous" : "Next"} ${{"车辆日对象":"vehicle-day item","浏览对象":"review item","行程":"trip","方向候选审查对象":"direction-candidate review item","方向候选":"direction candidate"}[type]}${rest}`]
